function safeOpGetter(contextOpId: string): (path: string) => Operator<IOperator> {
  return (path: string) => {
    const op = getOp(path, contextOpId)
    if (!op) {
      throw new Error(`Operator '${path}' not found`)
    }
    return op
  }
}

